import numpy as np
from scipy.spatial.transform import Rotation
P=np.array([[.1199,0,.5512],[.1199,-.0054,.6796],[.1199,-.0117,.89],[.1199,-.0181,1.1004],[.1199,-.0245,1.3088],[.1199,-.0247,1.4147],[.1199,-.0249,1.5207]])
AX=np.array([[0,0,-1],[0,1,0],[0,0,-1],[0,1,0],[0,0,-1],[0,1,0],[0,0,-1]])
EE=np.array([.1199,-.0249,1.7261]);CAM=np.array([.1199,.0315,1.5791]);FWD=np.array([0,0,1]);UP=np.array([0,1,0]);RIGHT=np.array([-1,0,0]);
def fk(q):
    R=np.eye(3);p=P[0].copy()
    origins=[];axes=[]
    for i in range(7):
        if i:p=p+R@(P[i]-P[i-1])
        origins.append(p.copy());axes.append(R@AX[i]);R=R@Rotation.from_rotvec(AX[i]*q[i]).as_matrix()
    return {'ee':p+R@(EE-P[-1]),'cam':p+R@(CAM-P[-1]),'fwd':R@FWD,'up':R@UP,'right':R@RIGHT,'R':R,'origins':np.array(origins),'axes':np.array(axes)}
if __name__=='__main__':
 q=[0,-.3490659,np.pi,-2.54818,0,-.87266463,np.pi/2];print(fk(q))
